"""Generate the canonical English and Turkish benchmark figures.

The figure set deliberately separates experiment stages:

* Figures 01--05: aligned F1 model-family screening (three-seed stage).
* Figure 06: confusion matrices for the selected release checkpoint.
* Figure 07: cross-domain analysis generated by ``scripts/28_canonical_report.py``.
* Figures 08--09: final H1/H2 dropout comparison under the seed-fixed pipeline.

Historical and exploratory figures are written by their own scripts under
``results/figures/historical`` or ``results/figures/supplementary``.
"""
from __future__ import annotations

import csv
import json
import shutil
import sys
from pathlib import Path

sys.stdout.reconfigure(encoding="utf-8")

import matplotlib
matplotlib.use("Agg")
import matplotlib.pyplot as plt
import numpy as np

PROJECT_ROOT = Path(__file__).resolve().parent.parent
CSV_DIR = PROJECT_ROOT / "results/csv"
RUNS_DIR = PROJECT_ROOT / "runs/completed"
FIG_DIR_EN = PROJECT_ROOT / "results/figures/en"
FIG_DIR_TR = PROJECT_ROOT / "results/figures/tr"
FIG_DIR_EN.mkdir(parents=True, exist_ok=True)
FIG_DIR_TR.mkdir(parents=True, exist_ok=True)

LABEL_NAMES = ["supported", "partially_supported", "contradicted", "unverifiable"]
LABEL_ABBREV_EN = ["Supported", "Partial", "Contradicted", "Unverifiable"]
LABEL_ABBREV_TR = ["Desteklendi", "Kısmen", "Çelişiyor", "Doğrulanamaz"]

F1_MODEL_SEEDS = [
    ("ELECTRA-TR\nLoRA r=16", "ELECTRA-TR\nLoRA r=16",
     ["F1_M04_ELECTRA_LORA16_S42", "F1_M04_ELECTRA_LORA16_S43", "F1_M04_ELECTRA_LORA16_S44"]),
    ("ModernBERT-TR\nLoRA r=16", "ModernBERT-TR\nLoRA r=16",
     ["F1_M12_MODERNBERT_LORA16_S42", "F1_M12_MODERNBERT_LORA16_S43", "F1_M12_MODERNBERT_LORA16_S44"]),
    ("ConvBERT-TR\nLoRA r=16", "ConvBERT-TR\nLoRA r=16",
     ["F1_M03_CONVBERT_LORA16_S42", "F1_M03_CONVBERT_LORA16_S43", "F1_M03_CONVBERT_LORA16_S44"]),
    ("BERT-32k\nFull FT*", "BERT-32k\nTam İnce Ayar*",
     ["F1_M01_BERT32K_FULLFT_S43", "F1_M01_BERT32K_FULLFT_S44", "F1_M01_BERT32K_FULLFT_S45"]),
    ("BERT-32k\nLoRA r=32", "BERT-32k\nLoRA r=32",
     ["F1_M01_BERT32K_LORA32_S42", "F1_M01_BERT32K_LORA32_S43", "F1_M01_BERT32K_LORA32_S44"]),
    ("BERT-128k\nLoRA r=16", "BERT-128k\nLoRA r=16",
     ["F1_M02_BERT128K_LORA16_S42", "F1_M02_BERT128K_LORA16_S43", "F1_M02_BERT128K_LORA16_S44"]),
    ("mBERT\nLoRA r=16", "mBERT\nLoRA r=16",
     ["F1_M07_MBERT_LORA16_S42", "F1_M07_MBERT_LORA16_S43", "F1_M07_MBERT_LORA16_S44"]),
]

SELECTED_RUN_ID = "H1_DROP10_S45"
FINAL_SERIES = {
    "H1 / dropout=0.10": [f"H1_DROP10_S{s}" for s in (42, 43, 44, 45, 46)],
    "H2 / dropout=0.00": [f"H2_DROP0_S{s}" for s in (42, 43, 44, 45, 46)],
}
SEEDS = [42, 43, 44, 45, 46]


def read_csv(path: Path) -> list[dict[str, str]]:
    with path.open(encoding="utf-8-sig", newline="") as handle:
        return list(csv.DictReader(handle))


def load_metrics() -> dict[str, dict[str, dict[str, str]]]:
    data: dict[str, dict[str, dict[str, str]]] = {}
    for row in read_csv(CSV_DIR / "metrics_long_canonical.csv"):
        data.setdefault(row["run_id"], {})[row["eval_set"]] = row
    return data


def safe_float(value: object, default: float = 0.0) -> float:
    try:
        return float(value)
    except (TypeError, ValueError):
        return default


def values(metrics, run_ids, eval_set, key="macro_f1") -> list[float]:
    vals = [safe_float(metrics.get(run_id, {}).get(eval_set, {}).get(key), float("nan")) for run_id in run_ids]
    return [v for v in vals if np.isfinite(v)]


def avg_f1(metrics, run_ids, eval_set, key="macro_f1") -> float:
    vals = values(metrics, run_ids, eval_set, key)
    return float(np.mean(vals)) if vals else 0.0


def avg_per_class(metrics, run_ids, eval_set) -> list[float]:
    return [avg_f1(metrics, run_ids, eval_set, f"{label}_f1") for label in LABEL_NAMES]


def save_bilingual_alias(path: Path, legacy_name: str | None = None) -> None:
    """Optionally retain a compatibility alias without changing figure contents."""
    if legacy_name:
        alias = path.parent / legacy_name
        if alias != path:
            shutil.copy2(path, alias)


def fig_01_model_comparison(metrics, lang="en"):
    fdir = FIG_DIR_EN if lang == "en" else FIG_DIR_TR
    labels = [entry[0 if lang == "en" else 1] for entry in F1_MODEL_SEEDS]
    seed_lists = [entry[2] for entry in F1_MODEL_SEEDS]
    d960 = [avg_f1(metrics, runs, "DEV960-GEN") for runs in seed_lists]
    d600 = [avg_f1(metrics, runs, "DEV600-STR") for runs in seed_lists]

    x, width = np.arange(len(labels)), 0.35
    fig, ax = plt.subplots(figsize=(12, 6.6))
    bars1 = ax.bar(x - width / 2, d960, width, label="DEV960-GEN (General)" if lang == "en" else "DEV960-GEN (Genel)")
    bars2 = ax.bar(x + width / 2, d600, width, label="DEV600-STR (Stress)" if lang == "en" else "DEV600-STR (Stres)")
    for bar in [*bars1, *bars2]:
        ax.text(bar.get_x() + bar.get_width() / 2, bar.get_height() + 0.005, f"{bar.get_height():.3f}", ha="center", fontsize=8)
    ax.set_xticks(x)
    ax.set_xticklabels(labels, fontsize=9)
    ax.set_ylim(0, 1.08)
    ax.set_ylabel("Macro F1")
    if lang == "en":
        title = "Aligned model-family screening — F1 series (3-seed mean)"
        note = "Screening-stage results; not the final H1/H2 checkpoint comparison. * Full-FT row uses seeds 43/44/45."
    else:
        title = "Eşlenmiş model ailesi taraması — F1 serisi (3 tohum ortalaması)"
        note = "Tarama aşaması sonuçlarıdır; nihai H1/H2 checkpoint karşılaştırması değildir. * Tam ince ayar satırı 43/44/45 tohumlarını kullanır."
    ax.set_title(title, fontsize=12)
    ax.text(0.5, -0.18, note, transform=ax.transAxes, ha="center", va="top", fontsize=8.5)
    ax.legend()
    ax.grid(axis="y", linestyle="--", alpha=0.35)
    fig.subplots_adjust(bottom=0.25)
    out = fdir / "fig_01_model_comparison_bar.png"
    plt.savefig(out, dpi=180, bbox_inches="tight")
    plt.close()
    print(f"  [OK] {lang}/{out.name}")


def fig_02_rank_scaling(metrics, lang="en"):
    fdir = FIG_DIR_EN if lang == "en" else FIG_DIR_TR
    rank_runs = [
        ("B1_M01_BERT32K_ALLLINEAR_LORA8_S42", "r=8\n(1.3M)"),
        ("B1_M01_BERT32K_ALLLINEAR_LORA16_S42", "r=16\n(2.7M)"),
        ("B1_M01_BERT32K_LORA32_S42", "r=32\n(5.4M)"),
    ]
    full_ft = "B1_M01_BERT32K_FULL_FT_S42"
    x = np.arange(len(rank_runs))
    d960 = [safe_float(metrics[r]["DEV960-GEN"]["macro_f1"]) for r, _ in rank_runs]
    d600 = [safe_float(metrics[r]["DEV600-STR"]["macro_f1"]) for r, _ in rank_runs]
    ft960 = safe_float(metrics[full_ft]["DEV960-GEN"]["macro_f1"])
    ft600 = safe_float(metrics[full_ft]["DEV600-STR"]["macro_f1"])
    fig, ax = plt.subplots(figsize=(8, 5.4))
    ax.plot(x, d960, "o-", label="DEV960-GEN", linewidth=2)
    ax.plot(x, d600, "s-", label="DEV600-STR", linewidth=2)
    ax.axhline(ft960, linestyle="--", alpha=0.55, label=f"Full FT DEV960 ({ft960:.3f})")
    ax.axhline(ft600, linestyle=":", alpha=0.55, label=f"Full FT DEV600 ({ft600:.3f})")
    for i, (v960, v600) in enumerate(zip(d960, d600)):
        ax.annotate(f"{v960:.3f}", (i, v960), xytext=(0, 8), textcoords="offset points", ha="center", fontsize=9)
        ax.annotate(f"{v600:.3f}", (i, v600), xytext=(0, -14), textcoords="offset points", ha="center", fontsize=9)
    ax.set_xticks(x)
    ax.set_xticklabels([label for _, label in rank_runs])
    ax.set_ylim(0.4, 1.0)
    ax.set_ylabel("Macro F1")
    ax.set_title("LoRA rank screening — BERT-32k, seed=42" if lang == "en" else "LoRA rank taraması — BERT-32k, tohum=42")
    ax.legend(fontsize=8.5)
    ax.grid(axis="y", linestyle="--", alpha=0.35)
    out = fdir / "fig_02_rank_scaling_line.png"
    plt.savefig(out, dpi=180, bbox_inches="tight")
    plt.close()
    print(f"  [OK] {lang}/{out.name}")


def fig_03_04_per_class_heatmap(metrics, lang="en"):
    fdir = FIG_DIR_EN if lang == "en" else FIG_DIR_TR
    row_labels = [entry[0 if lang == "en" else 1].replace("\n", " ") for entry in F1_MODEL_SEEDS]
    seed_lists = [entry[2] for entry in F1_MODEL_SEEDS]
    col_labels = LABEL_ABBREV_EN if lang == "en" else LABEL_ABBREV_TR
    for eval_set, filename, title_en, title_tr in [
        ("DEV960-GEN", "fig_03_per_class_heatmap_d960.png", "Per-class F1 — aligned F1 screening (DEV960)", "Sınıf bazlı F1 — eşlenmiş F1 taraması (DEV960)"),
        ("DEV600-STR", "fig_04_per_class_heatmap_d600.png", "Per-class F1 — aligned F1 screening (DEV600)", "Sınıf bazlı F1 — eşlenmiş F1 taraması (DEV600)"),
    ]:
        matrix = np.array([avg_per_class(metrics, runs, eval_set) for runs in seed_lists])
        fig, ax = plt.subplots(figsize=(9, 5))
        image = ax.imshow(matrix, aspect="auto", cmap="RdYlGn", vmin=0.5, vmax=1.0)
        plt.colorbar(image, ax=ax, label="F1")
        ax.set_xticks(range(4), col_labels)
        ax.set_yticks(range(len(row_labels)), row_labels)
        ax.set_title(title_en if lang == "en" else title_tr)
        for i in range(matrix.shape[0]):
            for j in range(matrix.shape[1]):
                ax.text(j, i, f"{matrix[i, j]:.3f}", ha="center", va="center", fontsize=9, color="white" if matrix[i, j] < 0.65 else "black")
        out = fdir / filename
        plt.savefig(out, dpi=180, bbox_inches="tight")
        plt.close()
        print(f"  [OK] {lang}/{filename}")


def fig_05_scatter(metrics, lang="en"):
    fdir = FIG_DIR_EN if lang == "en" else FIG_DIR_TR
    labels = [entry[0 if lang == "en" else 1].replace("\n", " ") for entry in F1_MODEL_SEEDS]
    seed_lists = [entry[2] for entry in F1_MODEL_SEEDS]
    d960 = [avg_f1(metrics, runs, "DEV960-GEN") for runs in seed_lists]
    d600 = [avg_f1(metrics, runs, "DEV600-STR") for runs in seed_lists]
    fig, ax = plt.subplots(figsize=(7, 6))
    for x, y, label in zip(d960, d600, labels):
        ax.scatter(x, y, s=100)
        ax.annotate(label, (x, y), xytext=(5, 3), textcoords="offset points", fontsize=7.5)
    ax.plot([0.55, 1.0], [0.55, 1.0], "k--", alpha=0.3)
    ax.set_xlim(0.55, 1.0)
    ax.set_ylim(0.55, 1.0)
    ax.set_xlabel("DEV960-GEN Macro F1")
    ax.set_ylabel("DEV600-STR Macro F1")
    ax.set_title("General vs stress performance — F1 screening" if lang == "en" else "Genel ve stres performansı — F1 taraması")
    ax.grid(linestyle="--", alpha=0.3)
    out = fdir / "fig_05_stress_vs_general_scatter.png"
    plt.savefig(out, dpi=180, bbox_inches="tight")
    plt.close()
    print(f"  [OK] {lang}/{out.name}")


def fig_06_confusion_matrix(lang="en"):
    fdir = FIG_DIR_EN if lang == "en" else FIG_DIR_TR
    report_path = RUNS_DIR / SELECTED_RUN_ID / "validation_report.json"
    report = json.loads(report_path.read_text(encoding="utf-8"))
    labels = LABEL_ABBREV_EN if lang == "en" else LABEL_ABBREV_TR
    for eval_set, key, suffix in [
        ("DEV960-GEN", "d960_confusion_matrix", "dev960"),
        ("DEV600-STR", "d600_confusion_matrix", "dev600"),
    ]:
        cm = np.array(report[key])
        cm_norm = cm / (cm.sum(axis=1, keepdims=True) + 1e-12)
        fig, axes = plt.subplots(1, 2, figsize=(13.5, 5.2))
        for ax, matrix, normalized in [(axes[0], cm, False), (axes[1], cm_norm, True)]:
            image = ax.imshow(matrix, cmap="Blues" if not normalized else "RdYlGn", vmin=0, vmax=1 if normalized else None)
            plt.colorbar(image, ax=ax)
            ax.set_xticks(range(4), labels, rotation=20, ha="right")
            ax.set_yticks(range(4), labels)
            ax.set_xlabel("Predicted" if lang == "en" else "Tahmin")
            ax.set_ylabel("Actual" if lang == "en" else "Gerçek")
            ax.set_title(("Normalized" if normalized else "Count") if lang == "en" else ("Normalize" if normalized else "Sayı"))
            for i in range(4):
                for j in range(4):
                    value = matrix[i, j]
                    text = f"{value:.2f}" if normalized else f"{int(value)}"
                    threshold = 0.5 if normalized else cm.max() / 2
                    ax.text(j, i, text, ha="center", va="center", color="white" if value > threshold else "black", fontsize=9)
        title = f"Selected checkpoint confusion matrix — {SELECTED_RUN_ID} ({eval_set})" if lang == "en" else f"Seçili checkpoint karışıklık matrisi — {SELECTED_RUN_ID} ({eval_set})"
        fig.suptitle(title, fontsize=12)
        out = fdir / f"fig_06_confusion_matrix_selected_{suffix}.png"
        plt.savefig(out, dpi=180, bbox_inches="tight")
        plt.close()
        print(f"  [OK] {lang}/{out.name}")
        if suffix == "dev960":
            save_bilingual_alias(out, "fig_06_confusion_matrix_best.png")


def final_stats(metrics, run_ids, eval_set):
    vals = values(metrics, run_ids, eval_set)
    return float(np.mean(vals)), float(np.std(vals, ddof=1)), vals


def fig_08_final_dropout_comparison(metrics, lang="en"):
    fdir = FIG_DIR_EN if lang == "en" else FIG_DIR_TR
    names = list(FINAL_SERIES)
    means_960, sd_960, means_600, sd_600 = [], [], [], []
    for name in names:
        m, s, _ = final_stats(metrics, FINAL_SERIES[name], "DEV960-GEN")
        means_960.append(m); sd_960.append(s)
        m, s, _ = final_stats(metrics, FINAL_SERIES[name], "DEV600-STR")
        means_600.append(m); sd_600.append(s)
    labels = ["Dropout 0.10\n(H1)" if lang == "en" else "Dropout 0,10\n(H1)", "Dropout 0.00\n(H2)" if lang == "en" else "Dropout 0,00\n(H2)"]
    x = np.arange(2); width = 0.35
    fig, ax = plt.subplots(figsize=(8.2, 5.8))
    b1 = ax.bar(x - width/2, means_960, width, yerr=sd_960, capsize=5, label="DEV960-GEN")
    b2 = ax.bar(x + width/2, means_600, width, yerr=sd_600, capsize=5, label="DEV600-STR")
    for bars in (b1, b2):
        for bar in bars:
            ax.text(bar.get_x()+bar.get_width()/2, bar.get_height()+0.004, f"{bar.get_height():.4f}", ha="center", fontsize=9)
    ax.set_xticks(x, labels)
    ax.set_ylim(0.78, 0.94)
    ax.set_ylabel("Macro F1")
    ax.set_title("Final seed-fixed dropout comparison — mean ± SD (5 seeds)" if lang == "en" else "Nihai seed-sabit dropout karşılaştırması — ortalama ± SS (5 tohum)")
    ax.legend()
    ax.grid(axis="y", linestyle="--", alpha=0.35)
    note = ("H1 selected: higher and more stable stress-set performance; H2 is stronger on the general set." if lang == "en" else "H1 seçildi: stres kümesinde daha yüksek ve daha kararlı; H2 genel kümede daha güçlü.")
    ax.text(0.5, -0.16, note, transform=ax.transAxes, ha="center", va="top", fontsize=8.5)
    fig.subplots_adjust(bottom=0.23)
    out = fdir / "fig_08_final_dropout_comparison.png"
    plt.savefig(out, dpi=180, bbox_inches="tight")
    plt.close()
    print(f"  [OK] {lang}/{out.name}")


def fig_09_final_seed_stability(metrics, lang="en"):
    fdir = FIG_DIR_EN if lang == "en" else FIG_DIR_TR
    fig, ax = plt.subplots(figsize=(9, 5.8))
    markers = {"H1 / dropout=0.10": ("o", "-"), "H2 / dropout=0.00": ("s", "--")}
    for name, run_ids in FINAL_SERIES.items():
        marker, linestyle = markers[name]
        vals960 = values(metrics, run_ids, "DEV960-GEN")
        vals600 = values(metrics, run_ids, "DEV600-STR")
        short = name.replace(" / ", " ")
        ax.plot(SEEDS, vals960, marker=marker, linestyle=linestyle, linewidth=1.8, label=f"{short} — DEV960")
        ax.plot(SEEDS, vals600, marker=marker, linestyle=":" if linestyle == "-" else "-.", linewidth=1.8, label=f"{short} — DEV600")
    ax.set_xticks(SEEDS)
    ax.set_ylim(0.79, 0.93)
    ax.set_xlabel("Seed" if lang == "en" else "Tohum")
    ax.set_ylabel("Macro F1")
    ax.set_title("Per-seed stability of the final dropout candidates" if lang == "en" else "Nihai dropout adaylarının tohum bazlı kararlılığı")
    ax.legend(fontsize=8.5, ncol=2)
    ax.grid(linestyle="--", alpha=0.3)
    out = fdir / "fig_09_final_seed_stability.png"
    plt.savefig(out, dpi=180, bbox_inches="tight")
    plt.close()
    print(f"  [OK] {lang}/{out.name}")


def main():
    print("=" * 64)
    print("TR-FactBench canonical figure generator — EN + TR")
    print("=" * 64)
    metrics = load_metrics()
    for lang in ("en", "tr"):
        print(f"\n--- {lang.upper()} ---")
        fig_01_model_comparison(metrics, lang)
        fig_02_rank_scaling(metrics, lang)
        fig_03_04_per_class_heatmap(metrics, lang)
        fig_05_scatter(metrics, lang)
        fig_06_confusion_matrix(lang)
        fig_08_final_dropout_comparison(metrics, lang)
        fig_09_final_seed_stability(metrics, lang)
    print(f"\n[DONE] EN={len(list(FIG_DIR_EN.glob('*.png')))} | TR={len(list(FIG_DIR_TR.glob('*.png')))}")


if __name__ == "__main__":
    main()
